class Solution {
    public int[] productExceptSelf(int[] nums) {
        int []suf = new int[nums.length];
        suf[nums.length-1] = 1;
        for(int i = suf.length-2;i>=0;i--){
            suf[i] = suf[i+1] * nums[i+1];
        }
        int num = 1;
        int[]res = new int[nums.length];
        res[0] = suf[0];
        for(int i = 1;i<nums.length;i++){
            num*=nums[i-1];
            res[i] = num*suf[i];
        }
        return res;
    }
}
